// รวบรวมคำศัพท์ใหม่โดยเริ่มนับ ID ต่อจาก 1230
let nextIdNum = 1231;
const newCards = [];

function addCard(word, pos, meaningTh, exampleEn, category, manaCost) {
  const cleanWord = word.trim();
  const k = cleanWord.toLowerCase();
  if (existingSet.has(k)) return;
  existingSet.add(k);

  newCards.push({
    id: `card-${String(nextIdNum).padStart(4, '0')}`,
    word: cleanWord,
    partOfSpeech: pos,
    meaningTh,
    exampleEn,
    category,
    manaCost: Math.min(5, Math.max(1, manaCost || 3)),
  });
  nextIdNum++;
}

// 1. เพิ่ม SEED_DICT
SEED_DICT.forEach(([w, pos, th, en, cat, mana]) => {
  addCard(w, pos, th, en, cat, mana);
});

